#include <filesystem>
#include <iomanip>
#include <iostream>
#include <utility>

int main() {
    const int width1{18}, width2{11}; // columns' width

    std::cout << std::left << std::setw(width1) << "Path:" << std::setw(width2)
              << "Ext:" << "Result:\n";
    for (const auto &[p, e] : {std::make_pair("/foo/bar.jpg", ".png"),
             {"/foo/bar.jpg", "png"}, {"/foo/bar.jpg", "."}, {"/foo/bar.jpg", ""},
             {"/foo/bar.", "png"}, {"/foo/bar", ".png"}, {"/foo/bar", "png"},
             {"/foo/bar", "."}, {"/foo/bar", ""}, {"/foo/.", ".png"}, {"/foo/.", "png"},
             {"/foo/.", "."}, {"/foo/.", ""}, {"/foo/", ".png"}, {"/foo/", "png"}}) {
        std::filesystem::path path{p}, ext{e};
        std::cout << std::setw(width1) << path << std::setw(width2) << ext;
        path.replace_extension(ext);
        std::cout << path << '\n';
    }
}
